1	export type ReceiptRow = {
2		id: string;
3		user_id: string;
4		receipt_image_path: string | null;
5		transaction_date: string | null; // ISO date (YYYY-MM-DD)
6		total_amount: number | null;
7		tax: number | null;
8		merchant_name: string | null;
9		credit_card_name: string | null;
10		credit_card_last_4: string | null;
11		currency: string | null;
12		exchange_rate_to_cad: number | null; // #{#fcr1a} Bank of Canada rate for transaction_date
13		matched_transaction_id: string | null;
14		created_at: string;
15		suspicious_date: boolean; // #{#dtv1b} - Flag for dates >42 days old or future
16		split_group_id?: string | null; // #{#spl1b} - Links receipts split from the same original
17		original_filename: string | null; // #{#ofn1a} - Original filename at time of upload (display-only)
18	};
