20	export class Receipt {
21		#id: string;
22		#userId: string;
23		#imagePath: string | null;
24		#transactionDate: string | null;
25		#totalAmount: number | null;
26		#tax: number | null;
27		#merchantName: string | null;
28		#creditCardName: string | null;
29		#creditCardLast4: string | null;
30		#currency: string | null;
31		#exchangeRateToCAD: number | null;
32		#matchedTransactionId: string | null;
33		#createdAt: string;
34		#suspiciousDate: boolean;
35		#splitGroupId: string | null;
36		#originalFilename: string | null;
