38		private constructor(row: ReceiptRow) {
39			this.#id = row.id;
40			this.#userId = row.user_id;
41			this.#imagePath = row.receipt_image_path;
42			this.#transactionDate = row.transaction_date;
43			this.#totalAmount = row.total_amount;
44			this.#tax = row.tax;
45			this.#merchantName = row.merchant_name;
46			this.#creditCardName = row.credit_card_name;
47			this.#creditCardLast4 = row.credit_card_last_4;
48			this.#currency = row.currency;
49			this.#exchangeRateToCAD = row.exchange_rate_to_cad;
50			this.#matchedTransactionId = row.matched_transaction_id;
51			this.#createdAt = row.created_at;
52			this.#suspiciousDate = row.suspicious_date;
53			this.#splitGroupId = row.split_group_id ?? null;
54			this.#originalFilename = row.original_filename;
55		}
56	
57		static fromRow(row: ReceiptRow) {
58			return new Receipt(row);
59		}
60	
61		toRow(): ReceiptRow {
62			return {
63				id: this.#id,
64				user_id: this.#userId,
65				receipt_image_path: this.#imagePath,
66				transaction_date: this.#transactionDate,
67				total_amount: this.#totalAmount,
68				tax: this.#tax,
69				merchant_name: this.#merchantName,
70				credit_card_name: this.#creditCardName,
71				credit_card_last_4: this.#creditCardLast4,
72				currency: this.#currency,
73				exchange_rate_to_cad: this.#exchangeRateToCAD,
74				matched_transaction_id: this.#matchedTransactionId,
75				created_at: this.#createdAt,
76				suspicious_date: this.#suspiciousDate,
77				split_group_id: this.#splitGroupId,
78				original_filename: this.#originalFilename
79			};
80		}
