132	export type ReceiptInsert = {
133		receipt_image_path?: string | null;
134		transaction_date?: string | null;
135		total_amount?: number | null;
136		tax?: number | null;
137		merchant_name?: string | null;
138		credit_card_name?: string | null;
139		credit_card_last_4?: string | null;
140		currency?: string | null;
141		exchange_rate_to_cad?: number | null; // #{#fcr1a}
142		matched_transaction_id?: string | null;
143		suspicious_date?: boolean; // #{#dtv1b} - Flag for suspicious dates
144		split_group_id?: string | null; // #{#spl1b} - Links receipts split from the same original
145		original_filename?: string | null; // #{#ofn1a} - Original filename at time of upload (display-only)
146	};
