1	import type { SupabaseClient } from '@supabase/supabase-js';
2	import type { ReceiptInsert, ReceiptRow } from '$lib/models/Receipt';
3	import { withRetry } from '$lib/utils/retry';
4	import type { ReceiptExtract } from '$lib/utils/sanitize';
5	import { isSuspiciousDate } from '$lib/utils/dateValidation';
6	import { resolveOcrReceiptDate } from '$lib/utils/receiptDateCorrection';
7	import { resizeImage } from '$lib/utils/imageResize';
8	import { getSignedReceiptUrl } from '$lib/utils/signedUrl';
9	import { sanitizeFilename } from '$lib/utils/sanitizeFilename';
10	
11	const IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/heic'];
12	const PDF_TYPE = 'application/pdf';
13	const MAX_IMAGE_MB = 5;
14	const MAX_PDF_MB = 10;
15	
16	/** The database row also carries family_id (set by trigger/RLS), which the model omits. */
17	type InsertedReceiptRow = ReceiptRow & { family_id: string | null };
18	
19	export class ReceiptService {
20		private supabase: SupabaseClient;
21	
22		constructor(supabase: SupabaseClient) {
23			this.supabase = supabase;
24		}
25	
26		/**
27		 * Call the server-side OCR API to extract receipt data
28		 */
29		private async extractOcrData(fileUrl: string, mimeType: string): Promise<ReceiptExtract | null> {
30			try {
31				const response = await fetch('/api/ocr/extract', {
32					method: 'POST',
33					headers: {
34						'Content-Type': 'application/json'
35					},
36					body: JSON.stringify({ fileUrl, mimeType })
37				});
38	
39				if (!response.ok) {
40					const errorText = await response.text();
41					throw new Error(`OCR API error: ${response.status} - ${errorText}`);
42				}
43	
44				const result = await response.json();
45				return result.data;
46			} catch (e) {
47				console.error('OCR extraction failed:', e);
48				return null;
49			}
50		}
51	
52		async list(
53			sort: 'transaction_date' | 'merchant_name' | 'total_amount' = 'transaction_date',
54			direction: 'asc' | 'desc' = 'desc'
55		) {
56			return withRetry(async () => {
57				const user = (await this.supabase.auth.getUser()).data.user;
58				if (!user) throw new Error('Not authenticated');
59	
60				console.log('[ReceiptService] Fetching receipts for user:', user.id);
61	
62				// Check family memberships for debugging
63				const { data: familyMemberships, error: fmError } = await this.supabase
64					.from('family_members')
65					.select('*')
66					.eq('user_id', user.id);
67				console.log('[ReceiptService] Family memberships:', familyMemberships, fmError);
68	
69				// Don't filter by user_id - let RLS policies handle access based on family membership
70				// This allows family members to see each other's receipts
71				const { data, error } = await this.supabase
72					.from('receipts')
73					.select('*')
74					.order(sort, { ascending: direction === 'asc' });
75				if (error) throw error;
76	
77				console.log('[ReceiptService] Fetched receipts:', {
78					count: data.length,
79					sample: data[0]
80						? {
81								id: data[0].id,
82								merchant_name: data[0].merchant_name,
83								family_id: data[0].family_id,
84								user_id: data[0].user_id
85							}
86						: 'none'
87				});
88	
89				return data as ReceiptRow[];
90			});
91		}
92	
93		/** Fields that are safe to send in an update — matches ReceiptInsert keys */
94		static readonly #EDITABLE_FIELDS: ReadonlySet<string> = new Set([
95			'receipt_image_path',
96			'transaction_date',
97			'total_amount',
98			'tax',
99			'merchant_name',
100			'credit_card_name',
101			'credit_card_last_4',
102			'currency',
103			'exchange_rate_to_cad',
104			'matched_transaction_id',
105			'suspicious_date',
106			'split_group_id'
107		]);
108	
109		async update(id: string, patch: ReceiptInsert) {
110			return withRetry(async () => {
111				// Strip non-editable fields (id, user_id, created_at, etc.) to prevent
112				// Supabase 400 errors from invalid values being sent in the update.
113				const safePatch: ReceiptInsert = {};
114				const source = patch as Record<string, unknown>;
115				const target = safePatch as Record<string, unknown>;
116				for (const key of Object.keys(patch)) {
117					if (ReceiptService.#EDITABLE_FIELDS.has(key)) {
118						target[key] = source[key];
119					}
120				}
121	
122				// #{#dtv1b} #{#dtv2d} Saving a receipt through the edit modal clears the
123				// suspicious-date flag. The modal always sends transaction_date, so a save
124				// (date corrected or left as-is) is treated as the user's review/confirmation
125				// of the date — there is no separate "confirm date" action. Only OCR/automated
126				// extraction sets the flag in the first place.
127				if ('transaction_date' in safePatch) {
128					safePatch.suspicious_date = false;
129				}
130	
131				const { data, error } = await this.supabase
132					.from('receipts')
133					.update(safePatch)
134					.eq('id', id)
135					.select('*')
136					.single();
137				if (error) throw error;
138				return data as ReceiptRow;
139			});
140		}
141	
142		async createManual(
143			values: Required<Pick<ReceiptInsert, 'merchant_name' | 'total_amount' | 'transaction_date'>> &
144				Partial<ReceiptInsert>
145		) {
146			return withRetry(async () => {
147				// Manual receipts are intentional - user is explicitly entering the date
148				// Skip suspicious date validation to avoid false positives for old receipts
149				const valuesWithFlag: ReceiptInsert = {
150					...values,
151					suspicious_date: false
152				};
153	
154				const { data, error } = await this.supabase
155					.from('receipts')
156					.insert(valuesWithFlag)
157					.select('*')
158					.single();
159				if (error) throw error;
160				return data as ReceiptRow;
161			});
162		}
163	
164		validateFile(file: File): { ok: true } | { ok: false; message: string } {
165			const type = file.type;
166			const sizeMB = file.size / (1024 * 1024);
167			if ([...IMAGE_TYPES, PDF_TYPE].indexOf(type) === -1) {
168				return { ok: false, message: 'Unsupported file type. Allowed: JPEG, PNG, HEIC, PDF.' };
169			}
170			if (IMAGE_TYPES.includes(type) && sizeMB > MAX_IMAGE_MB) {
171				return { ok: false, message: `Image too large. Max ${MAX_IMAGE_MB}MB.` };
172			}
173			if (type === PDF_TYPE && sizeMB > MAX_PDF_MB) {
174				return { ok: false, message: `PDF too large. Max ${MAX_PDF_MB}MB.` };
175			}
176			return { ok: true };
177		}
178	
179		/**
180		 * Upload a receipt file, extract its data via OCR, and persist the receipt row.
181		 *
182		 * Resilience invariants (see upload-pipeline-resilience spec):
183		 * - OCR is best-effort: any OCR failure still creates the receipt without extracted data.
184		 * - No orphan storage files: if the insert fails after upload, the blob is removed.
185		 */
186		async uploadAndCreate(file: File) {
187			const val = this.validateFile(file);
188			if (!val.ok) throw new Error(val.message);
189	
190			return withRetry(async () => {
191				const fileToUpload = await this.prepareFileForUpload(file);
192				const path = await this.uploadToStorage(fileToUpload);
193				const extract = await this.extractReceiptDataFailSoft(path, file.type);
194				const values = await this.buildReceiptInsert(file, path, extract);
195				const data = await this.insertReceiptOrCleanupUpload(values, path);
196				await this.autoAssignCategoryBestEffort(data, extract?.merchant_name ?? null);
197				return data as ReceiptRow;
198			});
199		}
200	
201		/** #{#rsz2a} Resize JPEG/PNG images before upload; falls back to the original on failure. */
202		private async prepareFileForUpload(file: File): Promise<File> {
203			const shouldResize = ['image/jpeg', 'image/png'].includes(file.type);
204			if (!shouldResize) return file;
205	
206			try {
207				const originalSize = file.size;
208				const resized = await resizeImage(file, 2000, 0.85);
209				const resizedSize = resized.size;
210	
211				console.log(
212					`Image resized: ${(originalSize / 1024).toFixed(2)}KB → ${(resizedSize / 1024).toFixed(2)}KB (${((1 - resizedSize / originalSize) * 100).toFixed(1)}% reduction)`
213				);
214				return resized;
215			} catch (error) {
216				console.error('Image resize failed, using original:', error);
217				return file; // Fall back to original
218			}
219		}
220	
221		/** Upload the file under the user's folder and return its storage path. Throws on failure. */
222		private async uploadToStorage(fileToUpload: File): Promise<string> {
223			const user = (await this.supabase.auth.getUser()).data.user;
224			if (!user) throw new Error('Not authenticated');
225			const folder = `${user.id}`;
226			const fileExt = fileToUpload.name.split('.').pop()?.toLowerCase() ?? 'bin';
227			const path = `${folder}/${crypto.randomUUID()}.${fileExt}`;
228			const { error: upErr } = await this.supabase.storage
229				.from('receipts')
230				.upload(path, fileToUpload, {
231					contentType: fileToUpload.type,
232					upsert: false
233				});
234			if (upErr) throw upErr;
235			return path;
236		}
237	
238		/**
239		 * #{#sec2a} OCR via a short-lived signed URL. Best-effort: returns null when the signed
240		 * URL cannot be generated or the OCR API fails, so the upload pipeline survives outages.
241		 */
242		private async extractReceiptDataFailSoft(
243			path: string,
244			mimeType: string
245		): Promise<ReceiptExtract | null> {
246			const signedUrl = await getSignedReceiptUrl(path, 300);
247			return signedUrl ? await this.extractOcrData(signedUrl, mimeType) : null;
248		}
249	
250		/** #{#fcr1a} #{#fcr2a} Fetch exchange rate at scan time for foreign currency receipts. */
251		private async fetchExchangeRateBestEffort(
252			currency: string | null,
253			transactionDate: string | null
254		): Promise<number | null> {
255			if (!currency || currency === 'CAD' || !transactionDate) return null;
256			try {
257				const { ExchangeRateService } = await import('./ExchangeRateService');
258				return await ExchangeRateService.fetchRate(currency, transactionDate);
259			} catch {
260				// Rate fetch is best-effort — receipt is saved without rate
261				return null;
262			}
263		}
264	
265		/** Map the (possibly null) OCR extract onto the row to insert. */
266		private async buildReceiptInsert(
267			file: File,
268			path: string,
269			extract: ReceiptExtract | null
270		): Promise<ReceiptInsert> {
271			// #{#rdc4b} #{#rdc5a} Correct OCR date from the verbatim raw string, then derive
272			// the suspicious_date flag (#{#dtv1b}) from the corrected value. Implausible,
273			// uncorrectable dates (wrong-token reads) are flagged rather than silently stored.
274			const { transaction_date: transactionDate, suspicious_date } = resolveOcrReceiptDate(
275				extract?.transaction_date ?? null,
276				extract?.raw_date_text,
277				new Date()
278			);
279			const currency = extract?.currency ?? null;
280			const exchangeRate = await this.fetchExchangeRateBestEffort(currency, transactionDate);
281	
282			return {
283				receipt_image_path: path,
284				original_filename: sanitizeFilename(file.name), // #{#ofn2a} capture original name (pre-resize)
285				transaction_date: transactionDate,
286				total_amount: extract?.total_amount ?? null,
287				tax: extract?.tax ?? null,
288				merchant_name: extract?.merchant_name ?? null,
289				currency: currency,
290				exchange_rate_to_cad: exchangeRate,
291				credit_card_name: extract?.credit_card_name ?? null,
292				credit_card_last_4: extract?.credit_card_last_4 ?? null,
293				suspicious_date
294			};
295		}
296	
297		/**
298		 * #{#upr1a} #{#upr1b} Insert the receipt row. If the insert fails, the storage upload has
299		 * already created a blob that no row will ever reference — remove it before re-throwing so
300		 * it doesn't become an orphan. Cleanup failure is logged but doesn't mask the original
301		 * insert error — the caller sees what went wrong with the insert.
302		 */
303		private async insertReceiptOrCleanupUpload(
304			values: ReceiptInsert,
305			path: string
306		): Promise<InsertedReceiptRow> {
307			const { data, error } = await this.supabase
308				.from('receipts')
309				.insert(values)
310				.select('*')
311				.single();
312			if (error) {
313				await this.removeUploadedFileBestEffort(path, error);
314				throw error;
315			}
316	
317			const row = data as InsertedReceiptRow;
318			console.log('[ReceiptService] Receipt created:', {
319				id: row.id,
320				merchant_name: row.merchant_name,
321				family_id: row.family_id,
322				user_id: row.user_id,
323				transaction_date: row.transaction_date
324			});
325			return row;
326		}
327	
328		/** Remove the just-uploaded blob; log (never throw) so the insert error stays visible. */
329		private async removeUploadedFileBestEffort(path: string, insertError: unknown): Promise<void> {
330			try {
331				const { error: removeErr } = await this.supabase.storage.from('receipts').remove([path]);
332				if (removeErr) {
333					console.error('orphan_storage_cleanup_failed', {
334						path,
335						insertError,
336						cleanupError: removeErr
337					});
338				}
339			} catch (cleanupError) {
340				console.error('orphan_storage_cleanup_failed', {
341					path,
342					insertError,
343					cleanupError
344				});
345			}
346		}
347	
348		/**
349		 * #{#vca2a} Auto-assign a category based on vendor rules. Graceful error handling:
350		 * failures are logged but never fail receipt creation.
351		 */
352		private async autoAssignCategoryBestEffort(
353			receipt: InsertedReceiptRow | null,
354			merchantName: string | null
355		): Promise<void> {
356			if (!merchantName || !receipt || !receipt.family_id) return;
357	
358			try {
359				// Dynamic import to avoid circular dependency
360				const { ExpenseService } = await import('./ExpenseService');
361				const expenseService = new ExpenseService(this.supabase);
362	
363				// Check for matching vendor rule using family_id
364				const vendorRule = await expenseService.getVendorRule(receipt.family_id, merchantName);
365				if (!vendorRule) return;
366	
367				// Auto-assign category with source='auto'
368				await expenseService.assignCategory(receipt.id, vendorRule.category_id, 'auto');
369	
370				// #{#vca3b} - Log auto-assignment for debugging
371				console.log(
372					JSON.stringify({
373						event: 'vendor_rule_auto_assign',
374						timestamp: new Date().toISOString(),
375						family_id: receipt.family_id,
376						receipt_id: receipt.id,
377						merchant_name: merchantName,
378						category_id: vendorRule.category_id,
379						category_name: vendorRule.category_name,
380						source: 'auto',
381						context: 'upload'
382					})
383				);
384			} catch (autoAssignError) {
385				// #{#vca2a} - Graceful error handling: log but don't fail receipt creation
386				console.error('Auto-assignment failed, receipt created without category:', autoAssignError);
387			}
388		}
389	
390		async delete(id: string, receiptImagePath?: string | null) {
391			return withRetry(async () => {
392				// determine storage path
393				let path = receiptImagePath ?? null;
394				if (!path) {
395					const { data, error } = await this.supabase
396						.from('receipts')
397						.select('receipt_image_path')
398						.eq('id', id)
399						.single();
400					if (error) throw error;
401					path = (data as { receipt_image_path: string | null } | null)?.receipt_image_path ?? null;
402				}
403	
404				// best-effort delete of storage object first to avoid orphan files
405				if (path) {
406					try {
407						await this.supabase.storage.from('receipts').remove([path]);
408					} catch {
409						// ignore storage deletion errors; proceed to delete DB row
410					}
411				}
412	
413				const { error: delErr } = await this.supabase.from('receipts').delete().eq('id', id);
414				if (delErr) throw delErr;
415				return { id };
416			});
417		}
418	
419		/**
420		 * #{#spl1a} Split a receipt into two partial receipts.
421		 *
422		 * Creates a new receipt with the specified split amount and reduces the
423		 * original receipt's amount accordingly. Both receipts share a split_group_id.
424		 *
425		 * @param receiptId The ID of the receipt to split
426		 * @param splitAmount The amount for the new split receipt
427		 * @returns The new receipt and the updated original
428		 */
429		async splitReceipt(
430			receiptId: string,
431			splitAmount: number,
432			splitDate?: string | null
433		): Promise<{ newReceipt: ReceiptRow; updatedOriginal: ReceiptRow }> {
434			// Validate inputs before any DB calls
435			ReceiptService.validateSplitAmount(splitAmount);
436			ReceiptService.validateSplitDate(splitDate);
437	
438			return withRetry(async () => {
439				// Auth check
440				const user = (await this.supabase.auth.getUser()).data.user;
441				if (!user) throw new Error('Not authenticated');
442	
443				const original = await this.fetchOriginalForSplit(receiptId);
444				const remainingAmount = ReceiptService.validateAndComputeRemaining(
445					original.total_amount,
446					splitAmount
447				);
448	
449				// #{#spl1b} - Determine split_group_id
450				const splitGroupId = original.split_group_id ?? crypto.randomUUID();
451	
452				// #{#spl5a} - Insert new receipt first, then update original
453				const newReceipt = await this.insertSplitReceipt(
454					ReceiptService.buildSplitReceiptInsert(original, splitAmount, splitDate, splitGroupId)
455				);
456				const updatedOriginal = await this.reduceOriginalAfterSplitOrRollback(
457					receiptId,
458					remainingAmount,
459					splitGroupId,
460					newReceipt.id
461				);
462	
463				return { newReceipt, updatedOriginal };
464			});
465		}
466	
467		/** #{#spl2b} Reject non-finite, non-positive, or sub-cent split amounts. */
468		private static validateSplitAmount(splitAmount: number): void {
469			if (!Number.isFinite(splitAmount) || splitAmount <= 0) {
470				throw new Error('Split amount must be a positive finite number');
471			}
472			// Check at most 2 decimal places
473			if (Math.round(splitAmount * 100) !== splitAmount * 100) {
474				throw new Error('Split amount can have at most 2 decimal places');
475			}
476		}
477	
478		/** #{#spl7c} Reject malformed or impossible (e.g. 2026-02-30) split dates when provided. */
479		private static validateSplitDate(splitDate?: string | null): void {
480			if (splitDate === undefined || splitDate === null) return;
481	
482			if (splitDate === '' || !/^\d{4}-\d{2}-\d{2}$/.test(splitDate)) {
483				throw new Error('Please enter a valid date');
484			}
485			const parsed = new Date(splitDate);
486			if (isNaN(parsed.getTime())) {
487				throw new Error('Please enter a valid date');
488			}
489			// Verify the date components match (catches 2026-02-30 etc.)
490			const [year, month, day] = splitDate.split('-').map(Number);
491			if (
492				parsed.getUTCFullYear() !== year ||
493				parsed.getUTCMonth() !== month - 1 ||
494				parsed.getUTCDate() !== day
495			) {
496				throw new Error('Please enter a valid date');
497			}
498		}
499	
500		private async fetchOriginalForSplit(receiptId: string): Promise<ReceiptRow> {
501			const { data: original, error: fetchError } = await this.supabase
502				.from('receipts')
503				.select('*')
504				.eq('id', receiptId)
505				.single();
506			if (fetchError) throw fetchError;
507			if (!original) throw new Error('Receipt not found');
508			return original as ReceiptRow;
509		}
510	
511		/**
512		 * Third split-validation step (after `validateSplitAmount` / `validateSplitDate`):
513		 * the total-relative rule. Unlike the other two it runs post-fetch because it needs
514		 * the original's total, and it returns the remainder it computes to validate — the
515		 * name says so rather than reading as a pure compute. Throws when the receipt has no
516		 * amount, or when the split isn't strictly less than the total (no positive remainder).
517		 */
518		private static validateAndComputeRemaining(
519			originalAmount: number | null,
520			splitAmount: number
521		): number {
522			if (originalAmount == null || originalAmount <= 0) {
523				throw new Error('Cannot split a receipt with no amount');
524			}
525			const remainingAmount = Math.round((originalAmount - splitAmount) * 100) / 100;
526			if (splitAmount >= originalAmount || remainingAmount <= 0) {
527				throw new Error('Split amount must be less than the receipt total');
528			}
529			return remainingAmount;
530		}
531	
532		/** The new split inherits the original's identity fields but never its transaction match. */
533		private static buildSplitReceiptInsert(
534			original: ReceiptRow,
535			splitAmount: number,
536			splitDate: string | null | undefined,
537			splitGroupId: string
538		): ReceiptInsert {
539			// #{#spl7a} - Use splitDate if provided, otherwise inherit from original
540			const effectiveDate = splitDate ?? original.transaction_date;
541	
542			// #{#spl7a} #{#spl7c} - Recalculate suspicious_date based on the split's own date
543			const effectiveSuspicious = splitDate ? isSuspiciousDate(splitDate) : original.suspicious_date;
544	
545			return {
546				receipt_image_path: original.receipt_image_path,
547				transaction_date: effectiveDate,
548				total_amount: splitAmount,
549				tax: null,
550				merchant_name: original.merchant_name,
551				credit_card_name: original.credit_card_name,
552				credit_card_last_4: original.credit_card_last_4,
553				currency: original.currency,
554				matched_transaction_id: null,
555				suspicious_date: effectiveSuspicious,
556				split_group_id: splitGroupId
557			};
558		}
559	
560		private async insertSplitReceipt(newReceiptData: ReceiptInsert): Promise<ReceiptRow> {
561			const { data: newReceipt, error: insertError } = await this.supabase
562				.from('receipts')
563				.insert(newReceiptData)
564				.select('*')
565				.single();
566			if (insertError) throw insertError;
567			return newReceipt as ReceiptRow;
568		}
569	
570		/**
571		 * #{#spl5a} Update the original (reduce amount, set split_group_id, clear match).
572		 * On failure, best-effort delete of the just-inserted split keeps the pair consistent.
573		 */
574		private async reduceOriginalAfterSplitOrRollback(
575			receiptId: string,
576			remainingAmount: number,
577			splitGroupId: string,
578			newReceiptId: string
579		): Promise<ReceiptRow> {
580			const { data: updatedOriginal, error: updateError } = await this.supabase
581				.from('receipts')
582				.update({
583					total_amount: remainingAmount,
584					matched_transaction_id: null,
585					split_group_id: splitGroupId
586				})
587				.eq('id', receiptId)
588				.select('*')
589				.single();
590	
591			if (updateError) {
592				// Rollback: delete the newly created receipt
593				try {
594					await this.supabase.from('receipts').delete().eq('id', newReceiptId);
595				} catch {
596					// Best-effort rollback
597				}
598				throw updateError;
599			}
600	
601			return updatedOriginal as ReceiptRow;
602		}
603	
604		/**
605		 * #{#blk3a} Bulk delete multiple receipts in a single database operation
606		 * @param receiptIds Array of receipt IDs to delete
607		 * @returns Promise that resolves when deletion is complete
608		 */
609		async bulkDeleteReceipts(receiptIds: string[]): Promise<{ deletedCount: number }> {
610			return withRetry(async () => {
611				// Get authenticated user
612				const user = (await this.supabase.auth.getUser()).data.user;
613				if (!user) throw new Error('Not authenticated');
614	
615				// Delete all receipts in a single query using IN clause
616				// Only delete receipts belonging to the authenticated user
617				const { error } = await this.supabase
618					.from('receipts')
619					.delete()
620					.in('id', receiptIds)
621					.eq('user_id', user.id);
622	
623				if (error) throw error;
624	
625				// Return metadata about deletion
626				return { deletedCount: receiptIds.length };
627			});
628		}
629	}
