3	/**
4	 * Converts a YYYY-MM-DD string to a Date object.
5	 * Returns undefined if the string is empty or invalid.
6	 */
7	export function toDate(isoString: string | null | undefined): Date | undefined {
8		if (!isoString) return undefined;
9		const parts = isoString.split('-');
10		if (parts.length !== 3) return undefined;
11		const year = parseInt(parts[0], 10);
12		const month = parseInt(parts[1], 10);
13		const day = parseInt(parts[2], 10);
14		if (isNaN(year) || isNaN(month) || isNaN(day)) return undefined;
15		return new Date(year, month - 1, day);
16	}
17	
18	/**
19	 * Formats a YYYY-MM-DD date string for display (e.g., "Mar 1, 2026").
20	 * Parses date parts manually to avoid timezone shift from new Date(string).
21	 */
22	export function formatDate(
23		isoString: string | null | undefined,
24		options: Intl.DateTimeFormatOptions = { year: 'numeric', month: 'short', day: 'numeric' }
25	): string {
26		if (!isoString) return '—';
27		const date = toDate(isoString);
28		if (!date) return '—';
29		return date.toLocaleDateString('en-US', options);
30	}
31	
32	/**
33	 * Narrows a flowbite `<Datepicker>` `onselect` value (`DateOrRange`) to a single
34	 * `Date | null`. Our pickers run in single-date mode, so `onselect` yields a bare
35	 * `Date`; for the range-object shape we take `from`. Returns null when no usable
36	 * date is present. Pair with `toISODateString()` to store the picked date.
37	 */
38	export function dateOrRangeToDate(value: DateOrRange | null | undefined): Date | null {
39		if (!value) return null;
40		if (value instanceof Date) return value;
41		return value.from ?? null;
42	}
43	
44	/**
45	 * Converts a Date object to a YYYY-MM-DD string.
46	 * Returns empty string if the date is null/undefined.
47	 */
48	export function toISODateString(date: Date | null | undefined): string {
49		if (!date || isNaN(date.getTime())) return '';
50		const year = date.getFullYear();
51		const month = String(date.getMonth() + 1).padStart(2, '0');
52		const day = String(date.getDate()).padStart(2, '0');
53		return `${year}-${month}-${day}`;
54	}
